function chatTopic(G,id){const L=CHAT[id]||[];G.chatSeen=G.chatSeen||{};const seen=G.chatSeen[id]||[];
  const hot=t=>/_(lost|won|final|beaten)$/.test(t.id)?0:1;const W=G.chatWkAbs||{};const ctx=L.filter(t=>t.need&&t.need(G)&&(!seen.includes(t.id)||(t.rep&&gameWeek(G)-(W[id+":"+t.id]??-999)>=t.rep))).sort((p,q)=>hot(p)-hot(q));if(ctx.length)return ctx[0];
  const gen=L.filter(t=>!t.need&&!seen.includes(t.id));if(gen.length)return gen[(G.week+G.seed)%gen.length];
  const all=L.filter(t=>!t.need).sort((a,b)=>seen.indexOf(a.id)-seen.indexOf(b.id));return all[0];}
// v1.27: she texts first, now and then, once you're close enough; an unread chat waits for you
const CHAT_BOND=15;
// v1.52: bonds fade a little when you haven't seen someone for a month — never below a stage already reached
const REL_FLOOR=[0,20,40,75];
const missGap=(G,id)=>{const f=G.F[id];if(!f||f.lastTouch==null)return 0;return absWeek(G)-f.lastTouch;};
function bondFade(G){G.relT=G.relT||{};for(const id of CANON_IDS){const f=G.F[id];if(!f||!f.met)continue;if(f.lastTouch==null){f.lastTouch=absWeek(G);continue;}
  const gap=absWeek(G)-f.lastTouch;if(gap<4)continue;const mine=f.camp==="player",rate=mine?.5:.25,floor=REL_FLOOR[G.relT[id]||0]||0;
  if((f.bondX||0)>0)continue;/* v1.86: past the first 100 the bond no longer fades */if(f.bond>floor)f.bond=Math.max(floor,Math.round((f.bond-rate)*100)/100);}}
function chatWeekly(G){bondFade(G);G.chatIn=G.chatIn||{};G.chatLast=G.chatLast||{};const rng=mulberry32(G.seed*31+G.week*7+3);
  for(const id of CANON_IDS){const f=G.F[id];if(!f||!f.met||G.chatIn[id])continue;
    {const L=CHAT[id]||[],seen=(G.chatSeen||{})[id]||[],W=G.chatWkAbs||{};if((f.bond||0)>=8&&gameWeek(G)-(G.chatLastAbs?.[id]??-999)>=1&&L.some(t=>t.need&&/_(lost|won|dm|flood|loan|miss|loy|loyw)$/.test(t.id)&&t.need(G)&&(!seen.includes(t.id)||(t.rep&&gameWeek(G)-(W[id+":"+t.id]??-999)>=t.rep)))){G.chatIn[id]=G.week;continue;}}
    if((f.bond||0)<CHAT_BOND)continue;
    if(gameWeek(G)-(G.chatLastAbs?.[id]??-999)<3)continue;if(rng()<.3+((f.bond||0)>=50?.1:0))G.chatIn[id]=G.week;}}
const chatLen=f=>3+((f.bond||0)>=40?1:0)+((f.bond||0)>=70?1:0);
const canChat=f=>!!(f&&f.met&&G.chatIn&&G.chatIn[f.id]);
function chatOpen(id){const f=G.F[id];if(!f||!canChat(f))return;f.lastTouch=absWeek(G);delete G.chatIn[id];G.chatLast=G.chatLast||{};G.chatLast[id]=G.week;G.chatLastAbs=G.chatLastAbs||{};G.chatLastAbs[id]=gameWeek(G);const T=chatTopic(G,id);
  G.chatSeen=G.chatSeen||{};G.chatSeen[id]=(G.chatSeen[id]||[]).filter(x=>x!==T.id).concat([T.id]);G.chatWk=G.chatWk||{};G.chatWk[id+":"+T.id]=G.week;G.chatWkAbs=G.chatWkAbs||{};G.chatWkAbs[id+":"+T.id]=gameWeek(G);
  const x=[...T.x];const ex=CHAT_X[id]||[];G.chatX=G.chatX||{};const xs=G.chatX[id]=G.chatX[id]||[];const extra=Math.min(1,chatLen(f)-3);for(let i=0;i<ex.length&&extra>0;i++)if(!xs.includes(i)&&(i===0||(f.bond||0)>=70)){x.push(ex[i]);xs.push(i);break;}
  const rng=mulberry32(G.seed+G.week*17+id.length);x.forEach(e=>{e.ord=[0,1,2].sort(()=>rng()-.5);});
  UI.chat={id,x,i:0,log:[{w:"them",t:x[0][0]}],gain:0,typing:false};UI.modal={type:"chat"};save();render();}
function chatPick(k){const C=UI.chat;if(!C||C.typing||C.i>=C.x.length)return;const e=C.x[C.i],o=e[1][k];if(!o)return;
  C.log.push({w:"me",t:o[0]});C.typing=true;AU.sfx("tick");render();
  setTimeout(()=>{if(UI.chat!==C)return;C.typing=false;C.log.push({w:"them",t:o[2],s:o[1]});if(o[1]>0){add(G,C.id,"bond",o[1]);C.gain+=o[1];}if(o[1]===2)AU.sfx("level");
    C.i++;if(C.i<C.x.length){C.typing=true;render();setTimeout(()=>{if(UI.chat!==C)return;C.typing=false;C.log.push({w:"them",t:C.x[C.i][0]});render();},700);}
    else{C.done=true;G.chatLog=G.chatLog||{};G.chatLog[C.id]=(G.chatLog[C.id]||0)+1;save();}render();},800);}
const CHAT_PX=pxIcon(["kkkkkkkkk.","kwwwwwwwk.","kwkwkwkwk.","kwwwwwwwk.","kkkwkkkkk.","..kk......"],{k:"#1b1230",w:"#f4f1ea"});
const HEART_PX=pxIcon([".kk.kk.","krrkrrk","krwrrrk","krrrrrk",".krrrk.","..krk..","...k..."],{k:"#4a1020",r:"#ff4d6d",w:"#ffd0da"});
function chatHTML(){const C=UI.chat;if(!C)return {body:"",foot:true};const f=G.F[C.id];
  const msgs=C.log.map(m=>`<div class="cmsg ${m.w}">${m.w==="them"?`<img class="cav" src="${faceSrc(f.id,"happy","casual")}" alt="">`:""}<p>${esc(m.w==="them"&&typeof nameCall==="function"?nameCall(C.id,m.t):m.t)}${m.s===2?`<i class="chrt">${HEART_PX}</i>`:""}</p></div>`).join("");
  const e=!C.done&&!C.typing&&C.x[C.i];
  return {foot:false,body:`<div class="chatw px"><div class="chead"><img src="${faceSrc(f.id,"happy","casual")}" alt=""><span><b>${esc(f.name)}</b><small>${C.typing?"กำลังพิมพ์…":"ออนไลน์"}</small></span><span class="cbond">${HEART_PX}<b class="num">${Math.round(f.bond||0)}</b></span></div>
   <div class="cbody pxscroll" data-sk="chat">${msgs}${C.typing?`<div class="cmsg them typing"><img class="cav" src="${faceSrc(f.id,"happy","casual")}" alt=""><p><i></i><i></i><i></i></p></div>`:""}</div>
   <div class="cfoot2">${e?`<small class="meta">เลือกข้อความที่จะพิมพ์ (${C.i+1}/${C.x.length})</small>${e.ord.map(k=>`<button class="copt" data-act="chatpick" data-v="${k}">${esc(e[1][k][0])}</button>`).join("")}`
     :C.done?`<p class="cend">${C.gain?`คุยกันถูกคอ · ความสนิทเพิ่มขึ้น`:"คุยกันสั้น ๆ วันนี้ ไว้เธอทักมาใหม่"}</p><button class="btn primary" data-act="closeModal">ปิดแชท</button>`:`<small class="meta">…</small>`}</div></div>`};}
XMODAL.chat=()=>chatHTML();
Object.assign(ACT,{chat:d=>chatOpen(d.id),chatpick:d=>chatPick(+d.v)});
XMODAL.confirm=m=>({body:`<h2>${m.title}</h2>${m.html||`<p>${m.text}</p>`}<div class="mfoot"><button class="btn ghost" data-act="${m.noAct||"closeModal"}" ${m.noV?`data-v="${m.noV}"`:""}>${m.no||"ไม่"}</button><button class="btn primary" data-act="${m.yes}">${m.ok||"ยืนยัน"}</button></div>`,foot:false});

